begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
delete from public.user_profiles;
insert into auth.users(id,email,email_confirmed_at) values
 ('41000000-0000-0000-0000-000000000001','operations-john@kapa.test',now()),
 ('41000000-0000-0000-0000-000000000002','operations-outsider@kapa.test',now());
insert into public.user_profiles(user_id,partner_id,display_name) select '41000000-0000-0000-0000-000000000001',id,'John' from public.partners where code='john';
update public.business_settings set energy_kwh_cost=1000,labor_hour_cost=5000;
create function pg_temp.op(action text,p jsonb) returns jsonb language sql as $$select public.business_operate(action,p,gen_random_uuid())$$;
create temp table operation_fixture(k text primary key,v jsonb);
grant select on operation_fixture to authenticated;
insert into operation_fixture values ('cost','{"printer_id":"51000000-0000-0000-0000-000000000001","description":"Pieza de prueba","quantity":"2","hours":"2","materials":[{"lot_id":"53000000-0000-0000-0000-000000000001","piece_grams":"10","support_grams":"2","waste_grams":"3"}],"labor_hours":"0.5","painting_hours":"0.25","painting_materials":"500","supplies_cost":"100","customization_cost":"200","packaging_cost":"300","other_cost":"400","multiplier":"3"}');

set local role anon;
select throws_ok($$select public.business_operate('customer_save','{}',gen_random_uuid())$$,'42501',null,'Anónimos no ejecutan operaciones');
reset role;
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000002';
set local role authenticated;
select is((select count(*) from public.cash_entries),0::bigint,'Un tercero no ve la caja');
select is((select count(*) from public.inventory_lots),0::bigint,'Un tercero no ve los materiales');
select throws_ok($$select public.business_read('catalog')$$,'42501','Acceso denegado','Un tercero no enumera clientes ni recursos');
select throws_ok($$select public.business_operate('cash_create','{"amount":100,"category":"capital"}',gen_random_uuid())$$,'42501','Acceso denegado','Un tercero no crea dinero');
select throws_ok('select private.op_cash_balance()','42501',null,'Los ayudantes privados no eluden permisos');
reset role;
set local request.jwt.claim.sub='41000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$insert into public.customers(name)values('Directo')$$,'42501',null,'Socios escriben solo mediante operaciones verificadas');
select lives_ok($$select public.business_operate('cash_create','{"amount":"500000","category":"capital","description":"Capital real de prueba","method":"transferencia"}','42000000-0000-0000-0000-000000000001')$$,'Registrar aporte');
select lives_ok($$select public.business_operate('cash_create','{"amount":"500000","category":"capital","description":"Capital real de prueba","method":"transferencia"}','42000000-0000-0000-0000-000000000001')$$,'Reintentar el aporte');
select is((select sum(amount) from public.cash_entries),500000.00::numeric,'No duplica dinero al reintentar');
select throws_ok($$select public.business_operate('cash_create','{"amount":"1","category":"capital"}','42000000-0000-0000-0000-000000000001')$$,'PT409','Identificador reutilizado con datos distintos.','Rechaza reutilizar clave para otra operación');
select lives_ok($$select pg_temp.op('printer_save','{"id":"51000000-0000-0000-0000-000000000001","name":"Impresora prueba","model":"A1 Mini","acquisition_cost":"1000000","useful_hours":"1000","power_kw":"0.1","status":"available"}')$$,'Configurar impresora sin inventar compra ni deuda');
select lives_ok($$select pg_temp.op('customer_save','{"id":"52000000-0000-0000-0000-000000000001","name":"Cliente de prueba"}')$$,'Crear cliente persistente');
select lives_ok($$select pg_temp.op('lot_purchase','{"id":"53000000-0000-0000-0000-000000000001","brand":"Prueba","kind":"PLA","color":"Verde","initial_grams":"1000","total":"90000","paid":"30000","installments":"3","installment_interest":"1000","description":"Rollo financiado"}')$$,'Comprar rollo con pago parcial y financiación');
select is((select sum(amount) from public.cash_entries),470000.00::numeric,'Solo el pago inicial descuenta caja');
select is((select principal from public.debts where description='Rollo financiado'),60000.00::numeric,'La parte no pagada se reconoce como deuda');
select is((select count(*) from public.debt_installments),3::bigint,'Crea las cuotas de financiación');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,0::numeric,'Ni el capital ni comprar inventario crean utilidad o gasto de material');
select lives_ok($$select pg_temp.op('debt_pay',jsonb_build_object('debt_id',(select id from public.debts where description='Rollo financiado'),'installment_id',(select i.id from public.debt_installments i join public.debts d on d.id=i.debt_id where d.description='Rollo financiado' and i.number=1),'principal','20000','interest','1000'))$$,'Pagar capital e interés por separado');
select is((select sum(amount) from public.cash_entries),449000.00::numeric,'Caja descuenta capital e interés efectivamente pagados');
select is((public.business_read('dashboard')->'summary'->>'debt_balance')::numeric,40000::numeric,'El abono reduce capital pendiente');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,-1000::numeric,'Solo el interés reduce utilidad, no se duplica el gasto de la compra');
select is((public.preview_production_cost((select v from operation_fixture where k='cost'))->>'total')::numeric,8800.00::numeric,'Motor calcula material, amortización, energía, trabajo, pintado y extras una vez');
select is((public.preview_production_cost((select v from operation_fixture where k='cost'))->>'price')::numeric,26400.00::numeric,'Multiplicador x3 no agrega de nuevo pintado ni personalización');
select is(round((public.preview_production_cost((select v from operation_fixture where k='cost'))->>'margin')::numeric,2),66.67::numeric,'Margen usa el precio de venta como denominador');
select is((public.preview_production_cost((select v from operation_fixture where k='cost'))->>'markup')::numeric,200::numeric,'Recargo se diferencia del margen');
select lives_ok($$select pg_temp.op('quote_create',jsonb_build_object('id','54000000-0000-0000-0000-000000000001','customer_id','52000000-0000-0000-0000-000000000001','description','Pedido prueba','lines',jsonb_build_array((select v from operation_fixture where k='cost'))))$$,'Guardar cotización con costo original');
select is((select price_total from public.quotes where id='54000000-0000-0000-0000-000000000001'),52800.00::numeric,'Cantidad multiplica el precio unitario');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000001'),1000::numeric,'Cotizar no consume material');
select lives_ok($$select pg_temp.op('order_create','{"id":"55000000-0000-0000-0000-000000000001","quote_id":"54000000-0000-0000-0000-000000000001","promised_at":"2030-01-01T12:00:00-05:00"}')$$,'Convertir cotización en pedido');
select is((select count(*) from public.material_reservations),0::bigint,'Crear pedido no consume ni reserva prematuramente');
select throws_ok($$select pg_temp.op('order_create','{"quote_id":"54000000-0000-0000-0000-000000000001","promised_at":"2030-01-01"}')$$,'PT409','Esta cotización ya fue convertida o cancelada.','No convierte una cotización dos veces');
select throws_ok($$select pg_temp.op('order_update','{"order_id":"55000000-0000-0000-0000-000000000001","version":1,"status":"ready"}')$$,'PT422','Sigue el flujo del pedido: anticipo, confirmación, producción, acabado y entrega.','No omite confirmación ni reservas con un cambio arbitrario de estado');
select throws_ok($$select pg_temp.op('order_update','{"order_id":"55000000-0000-0000-0000-000000000001","version":1,"status":"confirmed"}')$$,'PT422','Falta el anticipo. Confirma expresamente si autorizas producir sin él.','Exige anticipo o autorización explícita');
select lives_ok($$select pg_temp.op('order_payment','{"order_id":"55000000-0000-0000-0000-000000000001","amount":"26400"}')$$,'Cobrar anticipo del 50 %');
select lives_ok($$select pg_temp.op('order_update','{"order_id":"55000000-0000-0000-0000-000000000001","version":1,"status":"confirmed"}')$$,'Confirmar y reservar material');
select is((select grams from public.material_reservations where order_id='55000000-0000-0000-0000-000000000001'),30::numeric,'Reserva incluye soportes, purgado y cantidad');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000001'),1000::numeric,'Reservar no descuenta existencias físicas');
select throws_ok($$select pg_temp.op('inventory_adjust','{"lot_id":"53000000-0000-0000-0000-000000000001","delta_grams":"-980","kind":"waste","reason":"Prueba de merma"}')$$,'PT422','El ajuste dejaría stock negativo o afectaría reservas.','Protege el material comprometido');
select lives_ok($$select pg_temp.op('production_create',jsonb_build_object('id','56000000-0000-0000-0000-000000000001','line_id',(select id from public.order_lines where order_id='55000000-0000-0000-0000-000000000001'),'good_units','2','hours','4','materials','[{"lot_id":"53000000-0000-0000-0000-000000000001","piece_grams":"20","support_grams":"4","waste_grams":"6"}]'::jsonb,'labor_hours','1','painting_hours','0.5','painting_materials','1000','supplies_cost','200','customization_cost','400','packaging_cost','600','other_cost','800'))$$,'Registrar consumo y producción real atómicamente');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000001'),970::numeric,'Solo descuenta los 30 gramos reales una vez');
select is((select grams from public.material_reservations where order_id='55000000-0000-0000-0000-000000000001'),0::numeric,'Consumo libera la reserva utilizada');
select is((select accumulated_hours from public.printers where id='51000000-0000-0000-0000-000000000001'),4::numeric,'Acumula horas reales de la impresora');
select is((select cost_total from public.production_runs where id='56000000-0000-0000-0000-000000000001'),17600.00::numeric,'Conserva el costo real de producción completo');
select is((select sum(amount) from public.cash_entries),475400::numeric,'Producción y amortización no inventan salidas de caja');
select lives_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','55000000-0000-0000-0000-000000000001','version',(select version from public.orders where id='55000000-0000-0000-0000-000000000001'),'status','ready_delivery'))$$,'Pasar producción terminada a entrega');
select throws_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','55000000-0000-0000-0000-000000000001','version',(select version from public.orders where id='55000000-0000-0000-0000-000000000001'),'status','delivered'))$$,'PT422','Hay saldo pendiente. Autoriza expresamente la entrega a crédito.','La entrega con saldo exige autorización');
select lives_ok($$select pg_temp.op('order_payment','{"order_id":"55000000-0000-0000-0000-000000000001","amount":"26400"}')$$,'Cobrar saldo final');
select throws_ok($$select pg_temp.op('order_payment','{"order_id":"55000000-0000-0000-0000-000000000001","amount":"1"}')$$,'PT422','El cobro debe ser positivo y no superar el saldo del pedido.','No permite cobrar dos veces la venta');
select lives_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','55000000-0000-0000-0000-000000000001','version',(select version from public.orders where id='55000000-0000-0000-0000-000000000001'),'status','delivered'))$$,'Entregar pedido completamente producido y pagado');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Ganancia realizada: venta menos producción e interés, sin duplicar compra o deuda');
select is((public.business_read('dashboard')->'summary'->>'receivables')::numeric,0::numeric,'El cobro final cancela la cuenta por cobrar');
select is((select sum(amount) from public.cash_entries),501800::numeric,'Caja contiene una sola venta cobrada por anticipos y saldo');
select lives_ok($$select pg_temp.op('partner_advance',jsonb_build_object('partner_id',(select id from public.partners where code='john'),'amount','5000','description','Adelanto John'))$$,'Registrar adelanto como movimiento separado');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Adelantar al socio no genera gasto operativo');
select lives_ok($$select pg_temp.op('settlement_create',jsonb_build_object('period_start',current_date,'period_end',current_date,'reserve_amount','4200','notes','Liquidación de prueba'))$$,'Liquidar con reserva y compensar adelantos');
select is((select sum(amount) from public.partner_allocations where partner_id=(select id from public.partners where code='john')),15000::numeric,'John recibe exactamente el 50 % de 30.000');
select is((select sum(amount) from public.partner_allocations where partner_id=(select id from public.partners where code='sebas')),15000::numeric,'Sebas recibe exactamente el 50 % de 30.000');
select is((select sum(amount) from public.advance_compensations),5000::numeric,'Compensa el adelanto una vez en la liquidación');
select is((public.business_read('dashboard')->'partners'->0->>'balance')::numeric,10000::numeric,'Saldo John descuenta solo el adelanto compensado');
select is((select sum(amount) from public.cash_entries),496800::numeric,'Liquidar asignaciones no vuelve a descontar caja');
select lives_ok($$select pg_temp.op('partner_withdraw',jsonb_build_object('partner_id',(select id from public.partners where code='john'),'amount','10000','description','Retiro de utilidad asignada'))$$,'Pagar retiro disponible');
select throws_ok($$select pg_temp.op('partner_withdraw',jsonb_build_object('partner_id',(select id from public.partners where code='john'),'amount','1','description','Exceso'))$$,'PT422','El retiro supera la utilidad disponible del socio. Requiere autorización explícita y motivo.','Bloquea retiro superior al saldo sin autorización');
select throws_ok($$select pg_temp.op('settlement_create',jsonb_build_object('period_end',current_date,'reserve_amount','0'))$$,'PT422','No hay utilidad realizada sin liquidar suficiente.','No distribuye la misma ganancia dos veces');
select lives_ok($$select pg_temp.op('reserve_release',jsonb_build_object('period_end',current_date,'amount','2000','notes','Liberación parcial'))$$,'Liberar reserva sin crear nuevas ganancias');
select is((public.business_read('dashboard')->'summary'->>'business_reserve')::numeric,2200::numeric,'La reserva disminuye por su liberación');
select is((public.business_read('dashboard')->'summary'->>'unsettled_profit')::numeric,0::numeric,'Liberar una reserva no permite reconocer de nuevo la utilidad');
select lives_ok($$select pg_temp.op('inventory_adjust','{"id":"57000000-0000-0000-0000-000000000001","lot_id":"53000000-0000-0000-0000-000000000001","delta_grams":"-10","kind":"waste","reason":"Merma fuera de pedidos"}')$$,'Registrar merma trazable');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,33300::numeric,'La merma reconoce su costo real de inventario');
select lives_ok($$select pg_temp.op('inventory_reverse','{"movement_id":"57000000-0000-0000-0000-000000000001","reason":"Corrección de cantidad registrada"}')$$,'Compensar merma con registro contrario');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Compensación restaura el efecto económico una sola vez');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000001'),970::numeric,'Compensación restaura gramos sin borrar historial');
select throws_ok($$select pg_temp.op('inventory_reverse','{"movement_id":"57000000-0000-0000-0000-000000000001","reason":"Otra corrección"}')$$,'PT409','Este movimiento ya fue compensado.','Una merma no se compensa dos veces');
select throws_ok($$select pg_temp.op('production_reverse','{"production_id":"56000000-0000-0000-0000-000000000001","reason":"Pedido cerrado"}')$$,'PT409','La producción ya fue compensada o el pedido está cerrado.','No reescribe costos de una entrega cerrada');
select lives_ok($$select public.business_read('catalog'); select public.business_read('inventory'); select public.business_read('printers'); select public.business_read('customers'); select public.business_read('quotes'); select public.business_read('orders'); select public.business_read('queue'); select public.business_read('cash'); select public.business_read('debts'); select public.business_read('purchases'); select public.business_read('settlements'); select public.business_read('inventory_history')$$,'Todas las pantallas consultan recursos reales con permisos');
select lives_ok($$select public.preview_order_priority('55000000-0000-0000-0000-000000000001',2,0)$$,'Vista previa de prioridad no modifica compromisos');
select lives_ok($$select public.business_report('sales',current_date-1,current_date);select public.business_report('costs',current_date-1,current_date);select public.business_report('inventory',current_date-1,current_date);select public.business_report('consumption',current_date-1,current_date);select public.business_report('expenses',current_date-1,current_date);select public.business_report('debts',current_date-1,current_date);select public.business_report('cash',current_date-1,current_date);select public.business_report('partners',current_date-1,current_date);select public.business_report('products',current_date-1,current_date);select public.business_report('customers',current_date-1,current_date)$$,'Reportes reales sin depender de datos de demostración');
select lives_ok($$select public.business_report('cash',current_date-1,current_date,-1)$$,'Exportación completa se obtiene en una sola instantánea SQL');
select ok((select count(*)>20 from public.audit_log where actor_id='41000000-0000-0000-0000-000000000001'),'Las operaciones conservan auditoría con responsable');

select lives_ok($$select pg_temp.op('quote_create',jsonb_build_object('id','54000000-0000-0000-0000-000000000002','customer_id','52000000-0000-0000-0000-000000000001','description','Pedido a corregir','lines',jsonb_build_array((select v from operation_fixture where k='cost'))));select pg_temp.op('order_create','{"id":"55000000-0000-0000-0000-000000000002","quote_id":"54000000-0000-0000-0000-000000000002","promised_at":"2030-01-10T12:00:00-05:00"}');select pg_temp.op('order_payment','{"order_id":"55000000-0000-0000-0000-000000000002","amount":"26400"}');select pg_temp.op('order_update','{"order_id":"55000000-0000-0000-0000-000000000002","version":1,"status":"confirmed"}')$$,'Preparar otro pedido con reserva y anticipo');
select lives_ok($$select public.business_operate('production_create',jsonb_build_object('id','56000000-0000-0000-0000-000000000002','line_id',(select id from public.order_lines where order_id='55000000-0000-0000-0000-000000000002'),'good_units','2','hours','4','materials','[{"lot_id":"53000000-0000-0000-0000-000000000001","piece_grams":"30","support_grams":"0","waste_grams":"0"}]'::jsonb),'59000000-0000-0000-0000-000000000001')$$,'Producción con identificador de reintento');
select lives_ok($$select public.business_operate('production_create',jsonb_build_object('id','56000000-0000-0000-0000-000000000002','line_id',(select id from public.order_lines where order_id='55000000-0000-0000-0000-000000000002'),'good_units','2','hours','4','materials','[{"lot_id":"53000000-0000-0000-0000-000000000001","piece_grams":"30","support_grams":"0","waste_grams":"0"}]'::jsonb),'59000000-0000-0000-0000-000000000001')$$,'Reintento de producción tras respuesta perdida');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000001'),940::numeric,'Reintento no duplica gramos consumidos');
select is((select accumulated_hours from public.printers where id='51000000-0000-0000-0000-000000000001'),8::numeric,'Reintento no duplica horas de uso');
select lives_ok($$select pg_temp.op('production_reverse','{"production_id":"56000000-0000-0000-0000-000000000002","reason":"El registro no correspondía a una impresión realizada"}')$$,'Compensación autorizada de un registro incorrecto');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000001'),970::numeric,'Compensación de producción recupera el stock registrado incorrectamente');
select is((select accumulated_hours from public.printers where id='51000000-0000-0000-0000-000000000001'),4::numeric,'Compensación corrige las horas sin borrar el historial');
select throws_ok($$select pg_temp.op('production_create',jsonb_build_object('line_id',(select id from public.order_lines where order_id='55000000-0000-0000-0000-000000000002'),'good_units','2','hours','4','materials','[{"lot_id":"53000000-0000-0000-0000-000000000001","piece_grams":"1000"}]'::jsonb))$$,'PT422','Stock insuficiente para el consumo real; se respetan las reservas de otros pedidos.','Producción con stock insuficiente revierte toda la transacción');
select is((select count(*) from public.production_runs),2::bigint,'El error no deja una producción parcial');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000001'),970::numeric,'El error no altera existencias');
select throws_ok($$select pg_temp.op('order_cancel','{"order_id":"55000000-0000-0000-0000-000000000002","reason":"Cancelación por el cliente"}')$$,'PT422','Confirma que devolverás el dinero recibido antes de cancelar.','Cancelar un anticipo exige confirmar la devolución real');
select lives_ok($$select pg_temp.op('order_cancel','{"order_id":"55000000-0000-0000-0000-000000000002","reason":"Cancelación por el cliente","refund_confirmed":true}')$$,'Cancelar, devolver el cobro y liberar reservas atómicamente');
select is((select sum(amount) from public.cash_entries where order_id='55000000-0000-0000-0000-000000000002'),0::numeric,'La devolución compensa exactamente el anticipo');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Cancelar un pedido sin producción no inventa utilidad ni costo');
select throws_ok($$select pg_temp.op('printer_save','{"id":"51000000-0000-0000-0000-000000000099","name":"Inválida","model":"Inválida","acquisition_cost":"NaN"}')$$,'22023','Valor numérico inválido: acquisition_cost','Rechaza NaN en costos de impresora');
select throws_ok($$select pg_temp.op('inventory_adjust','{"lot_id":"53000000-0000-0000-0000-000000000001","delta_grams":"NaN","kind":"waste","reason":"Valor no finito"}')$$,'22023','Indica gramos y un motivo de al menos 5 caracteres.','Rechaza gramos no finitos');
select throws_ok($$select pg_temp.op('cash_create',jsonb_build_object('category','capital','description','Ingreso futuro','amount','100','date',current_date+2))$$,'22023','Registra dinero recibido o pagado, no movimientos futuros.','No inventa dinero futuro en caja');
select lives_ok($$select pg_temp.op('lot_purchase','{"id":"53000000-0000-0000-0000-000000000002","brand":"Prueba","kind":"PETG","color":"Negro","initial_grams":"1000","total":"10000","paid":"4000","description":"Compra para devolución"}')$$,'Compra financiada susceptible de devolución');
select throws_ok($$select pg_temp.op('purchase_void',jsonb_build_object('purchase_id',(select id from public.purchases where lot_id='53000000-0000-0000-0000-000000000002'),'reason','Devolución de rollo intacto'))$$,'PT422','Confirma el reembolso real recibido del proveedor.','La devolución de compra exige reembolso confirmado');
select lives_ok($$select pg_temp.op('purchase_void',jsonb_build_object('purchase_id',(select id from public.purchases where lot_id='53000000-0000-0000-0000-000000000002'),'reason','Devolución de rollo intacto','refund_confirmed',true))$$,'Devolver rollo intacto anula deuda, compensa inventario y devuelve el precio pagado');
select is((select on_hand_grams from public.inventory_lots where id='53000000-0000-0000-0000-000000000002'),0::numeric,'El rollo devuelto ya no figura como existencia');
select is((public.business_read('dashboard')->'summary'->>'debt_balance')::numeric,40000::numeric,'La devolución anula solo la deuda de esa compra');
select throws_ok($$select pg_temp.op('purchase_void',jsonb_build_object('purchase_id',(select id from public.purchases where lot_id='53000000-0000-0000-0000-000000000001'),'reason','Rollo usado no devolvible','refund_confirmed',true))$$,'PT422','Solo puedes devolver un rollo completo, sin consumir ni reservar.','No elimina un rollo que ya tuvo consumo');
select lives_ok($$select pg_temp.op('cash_create','{"category":"direct_sale","amount":"10000","direct_cost":"2000","description":"Venta directa corregida"}')$$,'Venta directa separa precio y costo económico');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,42200::numeric,'Venta directa reconoce solo su ganancia');
select lives_ok($$select pg_temp.op('cash_reverse',jsonb_build_object('cash_id',(select id from public.cash_entries where description='Venta directa corregida'),'reason','Corrección de venta directa'))$$,'Compensar venta directa conserva su historial');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Compensación de venta no duplica ni deja ganancias');
select is((public.business_read('dashboard')->'summary'->>'operating_expenses')::numeric,1000::numeric,'Compensar venta no se confunde con gasto operativo');
select lives_ok($$select pg_temp.op('cash_create','{"category":"energy","amount":"1000","description":"Energía ya costeada en producción","included_in_production":true}')$$,'Pago de un costo ya incluido mueve caja sin duplicarlo');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Pagar energía ya incorporada al costo no vuelve a reducir utilidad');
select lives_ok($$select pg_temp.op('purchase_create','{"description":"Insumos ya costeados","total":"2000","paid":"0","included_in_production":true}')$$,'Compra financiada ya costeada registra deuda sin duplicar costo');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'El costo ya asignado a producción se reconoce solo una vez');
select lives_ok($$select pg_temp.op('purchase_void',jsonb_build_object('purchase_id',(select id from public.purchases where description='Insumos ya costeados'),'reason','Devolución total sin pagos'))$$,'Compensación de compra sin pagos no inventa un reembolso');
select lives_ok($$select public.business_read('calendar','',0,current_date,current_date)$$,'Calendario consulta fechas comprometidas desde el servidor');
select lives_ok($$select pg_temp.op('cash_create','{"category":"expense","amount":"5000","description":"Pérdida posterior a liquidación"}')$$,'Registrar una pérdida después de liquidar');
select throws_ok($$select pg_temp.op('reserve_release',jsonb_build_object('period_end',current_date,'amount','1'))$$,'PT422','Reserva empresarial insuficiente después de cubrir pérdidas no liquidadas.','No libera reservas que se necesitan para absorber pérdidas posteriores');
select lives_ok($$select pg_temp.op('cash_reverse',jsonb_build_object('cash_id',(select id from public.cash_entries where description='Pérdida posterior a liquidación'),'reason','Corrección del gasto registrado'))$$,'Compensación corrige el efecto de la pérdida con historial');
select lives_ok($$select pg_temp.op('loan_create','{"id":"58000000-0000-0000-0000-000000000001","description":"Préstamo para prueba","amount":"5000","installments":"1"}')$$,'Préstamo crea caja y deuda, no utilidad');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Recibir crédito no aumenta ganancias');
select lives_ok($$select pg_temp.op('debt_pay',jsonb_build_object('debt_id',(select id from public.debts where description='Préstamo para prueba'),'principal','2500','interest','0'))$$,'Abono parcial sin cuota explícita se imputa a la primera pendiente');
select is((select sum(principal_paid) from public.debt_payments where installment_id=(select id from public.debt_installments where debt_id=(select id from public.debts where description='Préstamo para prueba'))),2500::numeric,'El plan de cuotas refleja también abonos realizados por API');
select lives_ok($$select pg_temp.op('debt_pay',jsonb_build_object('debt_id',(select id from public.debts where description='Préstamo para prueba'),'principal','2500','interest','0'))$$,'Segundo abono termina la cuota');
select is((public.business_read('dashboard')->'summary'->>'debt_balance')::numeric,40000::numeric,'Pagar principal cancela deuda sin generar nuevamente un gasto');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,34200::numeric,'Abonos de capital conservan la utilidad realizada');
select lives_ok($$select pg_temp.op('printer_save',jsonb_build_object('id','51000000-0000-0000-0000-000000000001','version',(select version from public.printers where id='51000000-0000-0000-0000-000000000001'),'name','Impresora prueba','model','A1 Mini','acquisition_cost','1000000','useful_hours','1000','power_kw','0.1','baseline_hours','100'))$$,'Configurar horas anteriores sin reescribir producción');
select is((select accumulated_hours from public.printers where id='51000000-0000-0000-0000-000000000001'),104::numeric,'Horas acumuladas suman referencia inicial y producción real neta');
select lives_ok($$select pg_temp.op('quote_create',jsonb_build_object('id','54000000-0000-0000-0000-000000000003','customer_id','52000000-0000-0000-0000-000000000001','description','Cola A','lines',jsonb_build_array((select v from operation_fixture where k='cost'))));select pg_temp.op('quote_create',jsonb_build_object('id','54000000-0000-0000-0000-000000000004','customer_id','52000000-0000-0000-0000-000000000001','description','Cola B','lines',jsonb_build_array((select v from operation_fixture where k='cost'))));select pg_temp.op('order_create','{"id":"55000000-0000-0000-0000-000000000003","quote_id":"54000000-0000-0000-0000-000000000003","promised_at":"2030-02-01T12:00:00-05:00"}');select pg_temp.op('order_create','{"id":"55000000-0000-0000-0000-000000000004","quote_id":"54000000-0000-0000-0000-000000000004","promised_at":"2030-02-02T12:00:00-05:00"}')$$,'Preparar dos pedidos para la misma impresora');
select ok((select (v->>'estimated_finish')::timestamptz>(v->>'previous_finish')::timestamptz from jsonb_array_elements(public.preview_order_priority('55000000-0000-0000-0000-000000000004',2,0))v where v->>'order_id'='55000000-0000-0000-0000-000000000003'),'Priorizar B muestra cuánto se posterga la estimación de A');
select ok((select (v->>'estimated_finish')::timestamptz<(v->>'previous_finish')::timestamptz from jsonb_array_elements(public.preview_order_priority('55000000-0000-0000-0000-000000000004',2,0))v where v->>'order_id'='55000000-0000-0000-0000-000000000004'),'Priorizar B adelanta su estimación en la vista previa');
select is((select promised_at from public.orders where id='55000000-0000-0000-0000-000000000003'),'2030-02-01T12:00:00-05:00'::timestamptz,'La prioridad no modifica la promesa al cliente');
select lives_ok($$select pg_temp.op('lot_purchase','{"id":"53000000-0000-0000-0000-000000000003","brand":"Precisión","kind":"PLA","color":"Prueba","initial_grams":"3","total":"1","paid":"0"}');select pg_temp.op('printer_save','{"id":"51000000-0000-0000-0000-000000000003","name":"Costos configurados en cero para prueba","model":"Prueba","acquisition_cost":"0","useful_hours":"1000","power_kw":"0"}')$$,'Preparar una tasa periódica de costo por gramo');
select is((public.preview_production_cost('{"printer_id":"51000000-0000-0000-0000-000000000003","hours":"1","materials":[{"lot_id":"53000000-0000-0000-0000-000000000003","piece_grams":"0.015"}]}')->>'total')::numeric,0.01::numeric,'PostgreSQL y decimal.js redondean medio centavo igual sin truncar primero la tasa por gramo');
select * from finish();
rollback;
